:root {
  /* 控制返回键的位置和大小 */
  --btn-back-translate-x: -8px; 
  --btn-back-translate-y: 1px; 
  --btn-back-scale: 0.9;         
/* 单独给返回键调个浅色 */
.header-btn-back {
  color: #ebd5d9 !important;
}
:root {
--header-btn-gap: -4px;
/* === 全局背景 === */
--chat-bg-color: #ffffff;
/* === 顶栏 === */
--chat-header-height: 65px;
--chat-header-bg: rgba(255, 253, 253, 0.85);
--chat-header-blur: 20px;
--chat-header-border: 1px #f2e9eb;
--chat-header-title-color: #5c4b51;
--chat-header-title-size: 15px;
--chat-header-subtitle-size: 12px;
--chat-header-icon-color: #dcb4bb;
/* === 顶栏头像 === */
--chat-header-avatar-size: 48px;
--chat-header-avatar-radius: 50%;
--chat-header-avatar-border: none; /* 边框在下面单独写了 */

/* === 底栏输入区 === */
--input-area-bg: #ffffff;
--input-area-blur: 20px;
--input-area-border-top: 1px solid #f2e9eb;
--input-box-bg: #ffffff;
--input-box-border: 1px solid #e5e5e8;
--input-box-color: #5c4b51;
--input-box-radius: 24px;
--send-btn-color: #dcb4bb;
--plus-btn-color: #dcb4bb;
/* === 气泡通用 === */
--bubble-them-padding: 8px 14px;
--bubble-me-padding: 8px 14px;
/* === 对方气泡（左） === */
--bubble-them-bg: #fafafa;
--bubble-them-border: 1px solid #efefef;
--bubble-them-color: #333333;
--bubble-them-radius: 7px;
/* === 我方气泡（右） === */
--bubble-me-bg: #fffbfb;
--bubble-me-border: 1px solid #f2e9eb;
--bubble-me-color: #5c4b51;
--bubble-me-radius: 7px;
/* === 独立引用条 === */
--reply-detached-bg: #ffffff;
--reply-detached-radius: 6px;
--reply-detached-padding: 6px 12px;
--reply-detached-border-left: none;
--reply-detached-filter: drop-shadow(0 1px 3px #f2e9eb);
--reply-detached-name-suffix: "：";
--reply-detached-align-items: baseline;
--reply-detached-name-size: 11px;
--plain-avatar-size: 40px;
}
/* === 顶栏自定义文案 & 名字前加@ === */
.chat-header-title::after {
content: "₊⁺淡淡的就会顺顺的⁺‧₊";
display: block;
font-size: 12px;
color: #998a8e;
font-weight: normal;
margin-top: 0px;
transform: translateX(2px);
}
.chat-header-title::before {
content: "@";
margin-right: 2px;
color: #dcb4bb;
font-weight: normal;
}
/* === 顶栏头像整体往左挪 === */
.header-profile-section {
margin-left: -16px !important;
transform: translateY(2px) !important;
}
/* === 顶栏头像：变圆 + 留白缝隙 + 粉色外框 === */
.header-avatar-container {
border-radius: 50% !important;
background-color: #ffffff !important;
padding: 2px !important;
border: 2px solid #e4c4ca!important;
position: relative !important;
overflow: visible !important;
transform: translateY(-4px) !important;
}
.header-avatar-container img,
.chat-header-avatar {
border-radius: 50% !important;
}
/* === 顶栏头像右下角的打钩圆圈 === */
.header-avatar-container::after {
content: "✓";
position: absolute;
bottom: -1px;
right: -6px;
width: 14px;
height: 14px;
background-color: #ebd5d9;
color: #fff;
font-size: 11px;
font-weight: bold;
border-radius: 50%;
display: flex !important;
align-items: center !important;
justify-content: center !important;
border: 2px solid #fff;
z-index: 10;
}
.header-btn-info svg {
opacity: 0 !important; /* 用透明代替隐藏，撑住原本的大小 */
}
/* === 聊天区头像显示控制 === */
.msg-avatar-them-inner,
.msg-avatar-me-inner,
.msg-avatar-container {
border-radius: 50% !important;
}
.msg-avatar-them-container { visibility: hidden; }
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single { visibility: visible; }
.msg-avatar-me-container { visibility: hidden; }
.msg-avatar-me-container.is-first,
.msg-avatar-me-container.is-single { visibility: visible; }
/* === 独立引用条逻辑 === */
.msg-reply-block { display: none !important; }
.msg-reply-block-detached {
display: flex !important;
order: -1 !important;
margin-bottom: 12px !important;
margin-top: 0 !important;
}
.msg-reply-detached-them,
.msg-reply-detached-me {
position: relative !important;
overflow: visible !important;
}
.msg-reply-detached-them::after,
.msg-reply-detached-me::after {
content: "" !important;
position: absolute !important;
bottom: -6px !important;
border-width: 6px 6px 0 6px !important;
border-style: solid !important;
border-color: #ffffff transparent transparent transparent !important;
}
.msg-reply-detached-them::after { left: 13px !important; }
.msg-reply-detached-me::after { right: 13px !important; }
/* === 头像对齐 & 气泡间距 === */
.msg-bubble-wrapper:has(.msg-reply-block-detached) .msg-avatar-them-container,
.msg-bubble-wrapper:has(.msg-reply-block-detached) .msg-avatar-me-container {
margin-top: 28px !important;
}
.msg-bubble-wrapper.msg-them { margin-bottom: 14px !important; }
.msg-bubble-wrapper.msg-me { margin-bottom: 10px !important; }
/* 允许名字显示在头像框外面 */
.msg-avatar-them-container,
.msg-avatar-me-container {
position: relative !important;
overflow: visible !important;
}
/* 默认把所有名字藏起来 */
.msg-avatar-them-container::after,
.msg-avatar-me-container::after {
display: none;
}
/* 只有在第一条或单条（也就是有头像时）才显示名字 */
.msg-avatar-them-container.is-first::after,
.msg-avatar-them-container.is-single::after,
.msg-avatar-me-container.is-first::after,
.msg-avatar-me-container.is-single::after {
display: block;
position: absolute;
font-size: 10px;
color: #ebd5d9;
white-space: nowrap;
}
/* 对方名字内容与位置 */
.msg-avatar-them-container::after {
content:"@" var(--char-name);
bottom: -16px; /* 上下：负数越小越往下 */
left: 4px;     /* 左右：正数往右，负数往左 */
}
/* 你的名字内容与位置 */
.msg-avatar-me-container::after {
content: "@池池";
bottom: -16px; /* 上下：负数越小越往下 */
right: 8px;    /* 左右：正数往左，负数往右 */
}
/* === 聊天区头像加圆框 === */
.msg-avatar-them-inner,
.msg-avatar-me-inner {
border: 1px solid #ebd5d9 !important;
padding: 2px !important;
background-color: #ffffff !important;
box-sizing: border-box !important;
border-radius: 50% !important;
}
/* 把里面的图片也强制变圆 */
.msg-avatar-them-inner img,
.msg-avatar-me-inner img {
border-radius: 50% !important;
}

/* === 头像往上挪一点 === */
.msg-avatar-them-container,
.msg-avatar-me-container {
  margin-top: -12px !important; /* 负数就是往上提，想多提就改-8、-10 */
}

/* === 保证和上一组消息的距离 === */
.msg-bubble-wrapper.is-first,
.msg-bubble-wrapper.is-single {
  margin-top: 18px !important; /* 把整组消息往下推，给提上来的头像留出安全距离 */
}
/* === 强行画上顶栏图标 === */
/* 1. 确保按钮全放出来，覆盖掉可能残留的隐藏代码 */
.header-btn-phone, .header-btn-video, .header-btn-info {
  display: flex !important;
  background-size: 18px !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 36px !important;
  height: 36px !important;
}
/* 2. 把系统自带的图标变透明 */
.header-btn-phone svg, .header-btn-video svg, .header-btn-info svg {
  opacity: 0 !important;
}
/* 3. 画上空心爱心（电话） */
.header-btn-phone {
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23ebd5d9' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z'/></svg>") !important;
transform: translateX(3px) !important;
}
/* 4. 画上实心爱心（视频） */
.header-btn-video {
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23ebd5d9'><path d='M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z'/></svg>") !important;
transform: translateX(3px) !important;
}
/* 5. 画上竖排三个点（设置） */
.header-btn-info {
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23ebd5d9'><circle cx='12' cy='4' r='1.8'/><circle cx='12' cy='12' r='1.8'/><circle cx='12' cy='20' r='1.8'/></svg>") !important;
  transform: translateX(4px) !important;
}
/* 强行给顶栏加底边框（单线） */
.chat-header-custom {
border-bottom: 1px solid #f2e9eb !important;
}
/* 1. 加号键自由定位 */
:root {
--btn-plus-translate-y: -50px; /* 负数往上，正数往下，你自己调 */
--btn-plus-translate-x: 0px;  /* 负数往左，正数往右 */
}
/* 2. 换输入框文案 & 解决重影 */
.input-box-custom::placeholder {
color: transparent !important;
-webkit-text-fill-color: transparent !important;
}
.input-action-bar-custom {
position: relative !important;
background: transparent !important; /* 把外层胶囊背景去掉 */
border: none !important; /* 把外层边框去掉 */
}
.input-box-custom {
background: #ffffff !important; /* 背景色单独给输入框 */
border: 1px solid #ebd5d9 !important; /* 边框单独给输入框 */
border-radius: 24px !important;
}
/* 自定义文案 */
.input-action-bar-custom::before {
content: ">ㅅ<人你有点萌萌呦! ⊹.";
position: absolute;
left: 82px;
top: 50%;
transform: translateY(-50%);
color: rgba(235, 213, 217, 0.6);
pointer-events: none;
z-index: 10;
font-size: 14px;
}
/* 打字时让新文案消失 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown))::before {
display: none;
}

/* 单独调左右位置 */
.input-btn-mic {
right: 52px !important; /* 语音靠左一点 */
}
.input-btn-sticker {
right: 10px !important; /* 表情靠右一点 */
}/* === 星星魔法核心 === */
/* 1. 屏蔽原生图标 */
.input-btn-plus svg, .input-btn-ai svg, .send-btn-custom svg {
opacity: 0 !important;
}
/* 2. 加号键：永远是实心星星，并暴力向上移 */
.input-btn-plus {
background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23ebd5d9'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") !important;
background-size: 26px !important;
background-repeat: no-repeat !important;
background-position: center !important;
}
/* 3. 发送键：实心星星，去底色 */
.send-btn-custom {
background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23ebd5d9'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") !important;
background-size: 26px !important;
background-repeat: no-repeat !important;
background-position: center !important;
background-color: transparent !important;
transform: translateX(10px) !important; /* 正数就是往右 */
}
/* 4. AI键（默认不打字时）：实心星星，在外面 */
.input-btn-ai {
background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23ebd5d9'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") !important;
background-size: 26px !important;
background-repeat: no-repeat !important;
background-position: center !important;
transition: all 0.2s ease !important; /* 加个丝滑的变形动画 */
transform: translateX(10px) !important; /* 正数就是往右 */
}
/* 5. AI键（打字时）：变成空心星星，脱离占位，钻进胶囊 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai {
position: absolute !important; /* 关键：让它飘起来，不挤占输入框的空间 */
right: 60px !important; /* 靠右的距离，刚好在发送键的左边，你可以微调 */
background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23ebd5d9' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><polygon points='12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2'/></svg>") !important;
background-size: 24px !important; /* 空心星星变小 */
z-index: 10 !important;

}
/* === 语音和表情的双拼悬浮小胶囊（终极版） === */
/* 1. 隐藏原生图标 */
.input-btn-mic svg, .input-btn-sticker svg {
display: none !important;
}
/* 2. 语音键（左半边） */
.input-btn-mic {
position: absolute !important;
top: -55px !important; /* 往上移了 */
right: 60px !important; /* 10 + 50 = 60，完美拼接，灰线回来了 */
background: rgba(255, 255, 255, 0.6) !important; /* 毛玻璃半透明白底 */
backdrop-filter: blur(10px) !important;
-webkit-backdrop-filter: blur(10px) !important;
border: 1px solid #f2e9eb !important; /* 粉色边框 */
border-radius: 20px 0 0 20px !important;
width: 50px !important;
height: 24px !important;
box-shadow: -2px 2px 6px rgba(0,0,0,0.02) !important;
transform: translateX(10px) !important;
}
.input-btn-mic::after {
content: "Voice";
font-size: 10px;
color: #ebd5d9;
position: absolute;
top: 50%; left: 50%;
transform: translate(-50%, -50%);
}
/* 3. 表情键（右半边） */
.input-btn-sticker {
position: absolute !important;
top: -55px !important;
right: 10px !important;
background: rgba(255, 255, 255, 0.6) !important;
backdrop-filter: blur(10px) !important;
-webkit-backdrop-filter: blur(10px) !important;
border: 1px solid #f2e9eb !important;
border-left: none !important; /* 去掉中间重合的线 */
border-radius: 0 20px 20px 0 !important;
width: 50px !important;
height: 24px !important;
box-shadow: 2px 2px 6px rgba(0,0,0,0.02) !important;
transform: translateX(10px) !important;
}
.input-btn-sticker::after {
content: "Memes";
font-size: 10px;
color: #ebd5d9;
position: absolute;
top: 50%; left: 50%;
transform: translate(-50%, -50%);
}

/* 解决打字时字和星星重叠 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-box-custom {
padding-right: 52px !important;
}
/* 1. 左边星星往上提一点，让它视觉居中 */
.input-btn-plus {
transform: translate(2px, -3px) !important; /* 前面的-6是往左，后面的-4是往上 */
}
/* 2. 胶囊整体往左挪，修正偏右的问题 */
.input-action-bar-custom {
transform: translateX(-4px) !important; /* 负数往左，看着图片大概差这么多 */
}
/* === 控制台专属配色（作者原味版） === */
.nuo-console-toggle-bar, .nuo-console-toggle-btn {
--console-toggle-bg: #fff7f2;
--console-toggle-color: #b07c6a;
}
.nuo-console-panel {
--console-panel-bg: rgba(255, 247, 242, 0.96);
--console-panel-color: #6d4f43;
}
/* 层级稍微压低一点，免得打架 */
.nuo-console-shell {
--console-shell-z: 10;
}

/* === 2. 我方最后一条消息智能避让胶囊 === */
/* 只有在输入框为空（胶囊存在）时，才往上顶。打字时胶囊消失，气泡自动掉下来 */
.chat-detail-screen:has(.input-box-custom:placeholder-shown) [data-absolute-last="true"][data-sender="me"] {
margin-bottom: 30px !important; /* 觉得不够远可以自己改大 */
}
/* === 2. 胶囊智能躲避：让 CSS 自己做加法（修复重叠bug） === */
.chat-detail-screen {
--offset-reply: 0px;
--offset-sendas-char: 0px;
--offset-sendas-narr: 0px;
--offset-console: 0px;
}
/* 各自独立报身高，绝不混淆 */
.chat-detail-screen:has(.input-reply-preview-bar) { --offset-reply: 50px; }
.chat-detail-screen:has(.input-sendas-char-bar) { --offset-sendas-char: 40px; }
.chat-detail-screen:has(.input-sendas-narration-bar) { --offset-sendas-narr: 40px; }
.chat-detail-screen:has(.nuo-console-shell) { --offset-console: 45px; }
/* 胶囊自动往上飞，高度 = 所有出现的条的高度总和 */
.input-btn-mic, .input-btn-sticker {
margin-top: calc(-1 * (var(--offset-reply) + var(--offset-sendas-char) + var(--offset-sendas-narr) + var(--offset-console))) !important;
/* 胶囊自动往上飞，并强行统一两半边的动画 */
.input-btn-mic, .input-btn-sticker {
margin-top: calc(-1 * (var(--offset-reply) + var(--offset-sendas-char) + var(--offset-sendas-narr) + var(--offset-console))) !important;
transition: all 0.2s cubic-bezier(0.25, 0.8, 0.25, 1) !important;}
}
/* 控制台出现时，保证胶囊在最上层不被盖住 */
.chat-detail-screen:has(.nuo-console-shell) .input-btn-mic,
.chat-detail-screen:has(.nuo-console-shell) .input-btn-sticker {
z-index: 50 !important;
}

/* === 3. 我方气泡避让胶囊 === */
/* 没打字（胶囊在）时，气泡往上躲 30px；一打字（胶囊消失），气泡自动掉下来 */
.chat-detail-screen:has(.input-box-custom:placeholder-shown) [data-absolute-last="true"][data-sender="me"] {
margin-bottom: 30px !important;
transition: margin-bottom 0.2s ease !important; /* 掉下来的时候也丝滑一点 */
}
/* === 气泡底部便签虚线（首尾封边 + 左右分色版） === */
/* 1. 给第一条、最后一条、单条气泡腾出底部空间 */
.msg-bubble-wrapper.is-first .bubble-them-custom,
.msg-bubble-wrapper.is-last .bubble-them-custom,
.msg-bubble-wrapper.is-single .bubble-them-custom,
.msg-bubble-wrapper.is-first .bubble-me-custom,
.msg-bubble-wrapper.is-last .bubble-me-custom,
.msg-bubble-wrapper.is-single .bubble-me-custom {
position: relative !important;
padding-bottom: 10px !important;
}

/* 2. 对方气泡（左边）的虚线：稍微加深一点的灰（用半透明黑） */
.msg-bubble-wrapper.is-first .bubble-them-custom::after,
.msg-bubble-wrapper.is-last .bubble-them-custom::after,
.msg-bubble-wrapper.is-single .bubble-them-custom::after {
content: "";
position: absolute;
left: 12px;
right: 12px;
bottom: 7px;
border-bottom: 1px dashed rgba(0, 0, 0, 0.12) !important; /* 嫌淡把0.12改大，比如0.15 */
pointer-events: none;
}
/* 3. 我方气泡（右边）的虚线：专属粉色加透明度 */
.msg-bubble-wrapper.is-first .bubble-me-custom::after,
.msg-bubble-wrapper.is-last .bubble-me-custom::after,
.msg-bubble-wrapper.is-single .bubble-me-custom::after {
content: "";
position: absolute;
left: 12px;
right: 12px;
bottom: 7px;
border-bottom: 1px dashed rgba(235, 213, 217, 0.6) !important; /* 嫌深把0.6改小，比如0.4 */
pointer-events: none;
}
/* === 独立翻译条（往内缩 + 浅粉色统一版） === */
:root {
--translation-always-show: 1;
}
.msg-translation-wrapper { display: none !important; }

