/* —— 操作鍵：抖音直播風「右側竖排操作欄」 —— */
.video-call-controls {
    background: linear-gradient(to top, rgba(0,0,0,0.5) 0%, transparent 45%) !important;
    align-items: stretch !important;
    padding: 0 !important;
