/* ── 3. 改造面板基础样式 (Ins 经典白底卡片) ── */
.chat-detail-screen {
  --thinking-panel-bg: #ffffff;
  --thinking-panel-border-full: 1px solid #dbdbdb; /* Ins 标准边框色 */
  --thinking-panel-border-left: none; 
  --thinking-panel-radius: 4px;
  --thinking-panel-shadow: 0 1px 2px rgba(0,0,0,0.02); /* 极弱的阴影，几乎扁平 */

