  --thinking-text-font-style: normal;
  --thinking-text-line-height: 1.5;
  --thinking-panel-overflow: visible;
}

/* ── 4. 核心魔法：全 SVG 多重背景绘制 Ins 界面 ── */
.nuo-thinking-panel {
    background-image: 
        var(--char-avatar), /* 图层1: 顶部头像 */
        /* 图层2: 顶部右侧“更多”图标 (三个点) */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23262626' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='12' cy='12' r='1.5'/><circle cx='19' cy='12' r='1.5'/><circle cx='5' cy='12' r='1.5'/></svg>"),
        /* 图层3: 顶部横向分割线 */
        linear-gradient(to right, #efefef, #efefef),
        /* 图层4: 底部左侧操作栏 (爱心、评论、纸飞机) */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='100' height='24' viewBox='0 0 100 24'><style>.icon{fill:none;stroke:%23262626;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;}</style><path class='icon' d='M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z' transform='translate(0,0)'/><path class='icon' d='M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z' transform='translate(38,0)'/><g transform='translate(76,0)'><line class='icon' x1='22' y1='2' x2='11' y2='13'/><polygon class='icon' points='22 2 15 22 11 13 2 9 22 2'/></g></svg>"),
        /* 图层5: 底部右侧“收藏”图标 */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23262626' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'><path d='M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z'/></svg>"),
        /* 图层6: 底部文字 (点赞数 + 时间) */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='40' viewBox='0 0 200 40'><style>.likes{font-family:system-ui,-apple-system,sans-serif;font-size:13px;font-weight:600;fill:%23262626;}.time{font-family:system-ui,-apple-system,sans-serif;font-size:11px;fill:%238e8e8e;}</style><text x='0' y='14' class='likes'>10,245 次赞</text><text x='0' y='34' class='time'>2 小时前</text></svg>") !important; 

    /* 📐 控制各个图层的大小 */
    background-size: 
        32px 32px, /* 图层1: 头像大小 */
        20px 20px, /* 图层2: 更多图标大小 */
        100% 1px,  /* 图层3: 分割线贯穿全宽 */
        100px 24px, /* 图层4: 左侧操作栏大小 */
        24px 24px, /* 图层5: 收藏图标大小 */
        200px 40px !important; /* 图层6: 底部文字大小 */

    /* 📍 控制各个图层的位置 */
    background-position: 
        16px 12px, /* 图层1: 头像 (左上角) */
        calc(100% - 16px) 18px, /* 图层2: 更多图标 (右上角) */
        0 56px, /* 图层3: 分割线 (头像下方) */
        16px calc(100% - 54px), /* 图层4: 操作栏 (距底54px) */
        calc(100% - 16px) calc(100% - 54px), /* 图层5: 收藏 (距底54px，靠右) */
        16px calc(100% - 8px) !important; /* 图层6: 文字 (最底部) */

    background-repeat: no-repeat !important;
}

/* ── 5. 强制头像变成正圆 (Ins风格) ── */
.nuo-thinking-panel {
    /* 利用伪元素遮罩或者直接在背景图上无法改圆角，但我们可以用一个巧妙的技巧 */
    /* 实际上 var(--char-avatar) 只是图片，圆角由系统控制，这里我们不强求，通常已经是圆的了 */
}

/* ── 6. 绘制顶部 Header 的名字 ── */
.nuo-thinking-panel::before {
    content: var(--char-name) !important;
    position: absolute !important;
    top: 18px !important;
    left: 58px !important;
    font-size: 14px !important;
    font-weight: 600 !important;
    color: #262626 !important;
    z-index: 2 !important;
    display: block !important;
}

/* ── 7. 清空原本的 after ── */
.nuo-thinking-panel::after {
    display: none !important;
}

/* =========================================================
   ⏱️ 聊天界面时间戳美化：灰色胶囊风格
   ========================================================= */

/* ── 1. 消息之间的时间戳 (如：下午 2:30) ── */
.timestamp-custom {
    background-color: rgba(0, 0, 0, 0.06) !important; /* 极浅的灰色背景 */
    color: #8e8e8e !important; /* 经典的次级灰文字 */
    padding: 4px 12px !important; /* 撑开胶囊的内边距 */
    border-radius: 100px !important; /* 完美的胶囊圆角 */
    font-size: 11px !important;
    font-weight: 500 !important;
    width: fit-content !important; /* 宽度紧贴文字 */
    margin: 16px auto 12px auto !important; /* 保证绝对居中，上下留白 */
    backdrop-filter: blur(4px) !important; /* 微微的毛玻璃质感 */
}

/* ── 2. 日期分隔线 (如：今天、昨天) 保持同款胶囊风格 ── */
:root {
    --date-divider-bg: rgba(0, 0, 0, 0.06);
    --date-divider-color: #8e8e8e;
    --date-divider-size: 11px;
    --date-divider-weight: 500;
    --date-divider-padding: 4px 12px;
    --date-divider-radius: 100px;
    --date-divider-margin: 16px 0;
}
